#!/usr/bin/env python3
"""Optional NetworkX reference on the exact workloads generated by phase5_bench."""
from __future__ import annotations

import argparse
import csv
import json
import statistics
import subprocess
import sys
import time
from pathlib import Path

from phase5_bench import (
    _independent_validation,
    load_snap_graph,
    make_actions,
    peak_rss_bytes,
    current_rss_bytes,
    percentile_ms,
    sha256_file,
)

DEFAULT_STATIC = ("email-eu-core", "wiki-vote", "soc-epinions1")
DEFAULT_DYNAMIC = ("email-eu-core", "wiki-vote")


def _worker(config):
    import networkx as nx
    import gc
    import hashlib
    import platform
    import random
    from phase5_bench import load_snap_graph

    archive = Path(config["dataset_path"])
    entry = config["entry"]
    parse_start = time.perf_counter_ns()
    n, edges, parse_stats = load_snap_graph(archive, entry)
    parse_ms = (time.perf_counter_ns() - parse_start) / 1e6
    actions = make_actions(
        n, edges, config["mode"], config["seed"], config["queries"],
        config["rounds"], config["updates_per_round"],
    )
    workload_hash = hashlib.sha256(
        json.dumps(actions, separators=(",", ":"), ensure_ascii=True).encode("ascii")
    ).hexdigest()
    rss_before = current_rss_bytes()
    workload_start = time.perf_counter_ns()
    cpu_start = time.process_time_ns()
    build_start = time.perf_counter_ns()
    graph = nx.DiGraph()
    graph.add_nodes_from(range(n))
    graph.add_edges_from(edges)
    build_ms = (time.perf_counter_ns() - build_start) / 1e6
    rss_after_build_with_input = current_rss_bytes()
    del edges
    gc.collect()
    rss_after_build = current_rss_bytes()

    update_ns = query_ns = 0
    query_latencies = []
    answers = []
    for action in actions:
        if action["kind"] in ("add", "remove"):
            start = time.perf_counter_ns()
            if action["kind"] == "add":
                for source, target in action["edges"]:
                    if graph.has_edge(source, target):
                        raise AssertionError("scheduled NetworkX insertion already exists")
                    graph.add_edge(source, target)
            else:
                for source, target in action["edges"]:
                    if not graph.has_edge(source, target):
                        raise AssertionError("scheduled NetworkX removal is absent")
                    graph.remove_edge(source, target)
            update_ns += time.perf_counter_ns() - start
            continue
        for source, target in action["pairs"]:
            start = time.perf_counter_ns()
            answer = nx.has_path(graph, source, target)
            elapsed = time.perf_counter_ns() - start
            query_latencies.append(elapsed)
            query_ns += elapsed
            answers.append(bool(answer))
    workload_ns = time.perf_counter_ns() - workload_start
    cpu_ms = (time.process_time_ns() - cpu_start) / 1e6
    return {
        "dataset_id": config["dataset_id"],
        "dataset_sha256": config["dataset_sha256"],
        "mode": config["mode"],
        "seed": config["seed"],
        "repeat": 0,
        "method": "networkx",
        "networkx_version": nx.__version__,
        "n": n,
        "initial_edges": parse_stats["normalized_directed_edges"],
        "updates": sum(len(a.get("edges", ())) for a in actions if a["kind"] in ("add", "remove")),
        "queries": len(answers),
        "parse_ms": parse_ms,
        "build_ms": build_ms,
        "update_ms": update_ns / 1e6,
        "query_ms": query_ns / 1e6,
        "workload_wall_ms": workload_ns / 1e6,
        "process_cpu_ms": cpu_ms,
        "query_latency_p50_ms": percentile_ms(query_latencies, .5),
        "query_latency_p95_ms": percentile_ms(query_latencies, .95),
        "query_latency_p99_ms": percentile_ms(query_latencies, .99),
        "rss_before_build_bytes": rss_before,
        "rss_after_build_with_input_buffer_bytes": rss_after_build_with_input,
        "rss_after_build_bytes": rss_after_build,
        "rss_delta_after_build_bytes": rss_after_build - rss_before if rss_after_build is not None and rss_before is not None else None,
        "process_peak_rss_bytes": peak_rss_bytes(),
        "workload_sha256": workload_hash,
        "answers": answers,
        "python": sys.version,
        "platform": platform.platform(),
    }


def _worker_main():
    config = json.loads(sys.stdin.buffer.read().decode("utf-8"))
    print(json.dumps(_worker(config), separators=(",", ":")))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--manifest", default="phase5_datasets.json")
    parser.add_argument("--data-dir", default="data/phase5_snap")
    parser.add_argument("--reference-csv", default="results/phase5/real_data/runs.csv")
    parser.add_argument("--out", default="results/phase5/networkx_reference")
    parser.add_argument("--datasets", default=",".join(DEFAULT_STATIC))
    parser.add_argument("--dynamic-datasets", default=",".join(DEFAULT_DYNAMIC))
    parser.add_argument("--seeds", type=int, default=3)
    parser.add_argument("--queries", type=int, default=1000)
    parser.add_argument("--rounds", type=int, default=2)
    parser.add_argument("--updates-per-round", type=int, default=8)
    parser.add_argument("--benchmark-dataset-order", default="email-eu-core,wiki-vote,soc-epinions1,web-google")
    args = parser.parse_args()
    root = Path(__file__).resolve().parent
    manifest_path = Path(args.manifest); manifest_path = manifest_path if manifest_path.is_absolute() else root / manifest_path
    data_dir = Path(args.data_dir); data_dir = data_dir if data_dir.is_absolute() else root / data_dir
    reference_csv = Path(args.reference_csv); reference_csv = reference_csv if reference_csv.is_absolute() else root / reference_csv
    out_dir = Path(args.out); out_dir = out_dir if out_dir.is_absolute() else root / out_dir
    if not reference_csv.exists():
        raise FileNotFoundError(f"complete primary benchmark first: {reference_csv}")
    if out_dir.exists() and any(out_dir.iterdir()):
        raise FileExistsError(f"refusing to overwrite {out_dir}")
    out_dir.mkdir(parents=True, exist_ok=True)

    manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    entries = {item["id"]: item for item in manifest["datasets"]}
    static_ids = [value.strip() for value in args.datasets.split(",") if value.strip()]
    dynamic_ids = {value.strip() for value in args.dynamic_datasets.split(",") if value.strip()}
    selected_ids = list(dict.fromkeys(static_ids + sorted(dynamic_ids - set(static_ids))))
    benchmark_order = [value.strip() for value in args.benchmark_dataset_order.split(",") if value.strip()]
    unknown = sorted((set(selected_ids) | dynamic_ids) - set(entries))
    if unknown:
        parser.error(f"unknown dataset IDs: {unknown}")
    if args.seeds < 1 or args.queries < 4:
        parser.error("seeds must be positive and queries >=4")

    reference = {}
    with reference_csv.open(newline="", encoding="utf-8") as stream:
        for row in csv.DictReader(stream):
            key = (row["dataset_id"], row["mode"], int(row["seed"]), int(row["repeat"]))
            reference.setdefault(key, row["workload_sha256"])

    rows = []
    for dataset_id in selected_ids:
        entry = entries[dataset_id]
        archive = data_dir / dataset_id / entry["filename"]
        if not archive.exists():
            raise FileNotFoundError(archive)
        actual_hash = sha256_file(archive)
        if entry.get("sha256") and actual_hash.lower() != entry["sha256"].lower():
            raise ValueError(f"archive SHA mismatch for {dataset_id}")
        dataset_index = benchmark_order.index(dataset_id)
        path = str(archive.resolve())
        modes = ["static"] + (["dynamic"] if dataset_id in dynamic_ids else [])
        for mode in modes:
            for seed_index in range(args.seeds):
                seed = 57000 + dataset_index * 1000 + seed_index
                n, edges, _ = load_snap_graph(archive, entry)
                actions = make_actions(n, edges, mode, seed, args.queries, args.rounds, args.updates_per_round)
                workload_hash = __import__("hashlib").sha256(
                    json.dumps(actions, separators=(",", ":"), ensure_ascii=True).encode("ascii")
                ).hexdigest()
                expected_hash = reference.get((dataset_id, mode, seed, 0))
                if expected_hash is None or expected_hash != workload_hash:
                    raise AssertionError(
                        f"NetworkX stream differs from primary benchmark: {dataset_id}/{mode}/{seed}; "
                        f"expected={expected_hash} actual={workload_hash}"
                    )
                del actions, edges
                config = {
                    "dataset_id": dataset_id,
                    "dataset_path": path,
                    "dataset_sha256": actual_hash,
                    "entry": {key: value for key, value in entry.items()
                              if key not in ("path", "parsed", "sha256", "file_size_bytes", "local_archive_excluded_from_git")},
                    "mode": mode,
                    "seed": seed,
                    "queries": args.queries,
                    "rounds": args.rounds,
                    "updates_per_round": args.updates_per_round,
                }
                start = time.perf_counter_ns()
                proc = subprocess.run(
                    [sys.executable, str(Path(__file__).resolve()), "--worker"],
                    input=json.dumps(config, separators=(",", ":")).encode("utf-8"),
                    capture_output=True,
                    check=True,
                )
                row = json.loads(proc.stdout)
                parent_wall = (time.perf_counter_ns() - start) / 1e6
                answers = row.pop("answers")
                oracle_start = time.perf_counter_ns()
                expected_answers, _, _ = _independent_validation(archive, entry, mode,
                    make_actions(n, load_snap_graph(archive, entry)[1], mode, seed,
                                 args.queries, args.rounds, args.updates_per_round))
                oracle_ms = (time.perf_counter_ns() - oracle_start) / 1e6
                if answers != expected_answers:
                    raise AssertionError(f"NetworkX differs from BFS oracle: {dataset_id}/{mode}/{seed}")
                row["workload_sha256_matches_primary"] = True
                row["accuracy_vs_independent_bfs"] = True
                row["oracle_validation_ms_excluded"] = oracle_ms
                row["parent_wall_including_startup_ms"] = parent_wall
                rows.append(row)
                print(f"networkx dataset={dataset_id} mode={mode} seed={seed} exact=true", flush=True)

    out_csv = out_dir / "runs.csv"
    with out_csv.open("w", newline="", encoding="utf-8") as stream:
        writer = csv.DictWriter(stream, fieldnames=list(rows[0]))
        writer.writeheader(); writer.writerows(rows)
    summary = {
        "title": "AETHER Phase 5 — optional NetworkX reference",
        "library": "NetworkX",
        "library_version": rows[0]["networkx_version"] if rows else None,
        "datasets": selected_ids,
        "dynamic_datasets": sorted(dynamic_ids),
        "seeds_per_dataset_mode": args.seeds,
        "same_workload_sha256_as_primary_for_all_runs": all(row["workload_sha256_matches_primary"] for row in rows),
        "all_answers_exact_vs_independent_bfs": all(row["accuracy_vs_independent_bfs"] for row in rows),
        "results": rows,
        "csv": str(out_csv),
        "limitations": [
            "NetworkX was installed only in a separate temporary virtual environment and is not a project/runtime dependency.",
            "This comparison covers directed reachability only; it does not implement the AETHER batch FFI API, shortest-path reconstruction API, or controller.",
            "NetworkX is measured on selected small and medium datasets. The 875,713-node web-Google graph is omitted from this external reference because its Python object graph would raise resource and time cost substantially; AETHER methods still include it.",
            "RSS is process-resident memory and includes interpreter and input-buffer costs; there is no directly comparable retained-heap estimator for NetworkX in this experiment.",
        ],
    }
    (out_dir / "summary.json").write_text(json.dumps(summary, indent=2), encoding="utf-8")
    print(json.dumps({"output": str(out_dir), "runs": len(rows), "all_exact": summary["all_answers_exact_vs_independent_bfs"]}, indent=2))


if __name__ == "__main__":
    if "--worker" in sys.argv:
        _worker_main()
    else:
        main()
